    !IsBlank(cmbPaneSaved_Filter.Selected.Filter),
    ClearCollect(
        colInventoryFilter,
            ParseJSON(cmbPaneSaved_Filter.Selected.Filter, FilterType) 
    )
);

// Build query based on filters
    udfQbBuildQuery();

// Changes visibility basd on chosen tab
    Switch( 
        tabPaneTabs_Filter.Selected.Value, 

        "Filter",
        Set(varViewPaneFilterTab, "Filter"),

        "JSON", 
        Set(varViewPaneFilterTab, "JSON"),

        "KQL", 
        Set(varViewPaneFilterTab, "KQL")

    )

// Open modal
    Set(varViewModal, true);

// Reset indicator for made changes in saved filter
