Rules.InvariantScript:
// Build the required resource-type filter and any enabled UI filters.
    udfQbBuildQuery();

// Execute only when validation and query generation succeeded.
    If(
        varQbReady,
        udfQbRunInventory()
    )

// Step 1: Validate the filter name.
If(
    IsBlank(Trim(txtModelFormFilterName.Text)),
    Notify(
        "Please enter a filter name.",
        NotificationType.Warning
    ),

    // Step 2: Attempt to save the filter.
    IfError(
        Set(
            varSavedInventoryQuery,
            Patch(
                'Inventory Queries',

                // Step 3: Check the selected record's unique ID.
                // No ID means create; an existing ID means update.
                If(
                    IsBlank(
                        cmbPaneSaved_Filter.Selected.'Inventory Queries'
                    ),
                    Defaults('Inventory Queries'),
                    cmbPaneSaved_Filter.Selected
                ),

                // Step 4: Set the values to save.
                {
                    Name: txtModelFormFilterName.Text,
                    Description: txtModelFormFilterDescription.Text,
                    Filter: JSON(
                        colInventoryFilter,
                        JSONFormat.Compact
                    ),
                    'Resource Type': varResource
                }
            )
        );

        // Step 5: Confirm that Dataverse returned a record ID.
        If(
            IsBlank(
                varSavedInventoryQuery.'Inventory Queries'
            ),
            Notify(
                "Saving could not be confirmed: no record ID was returned.",
                NotificationType.Error
            ),

            // Step 6: Run your Apply logic only in this success branch.
            Notify(
                "Filter saved successfully.",
                NotificationType.Success
            );

            // Reset form and ide modal
            Reset(txtModelFormFilterName);
            Reset(txtModelFormFilterDescription);
            Set(varViewModal, false)

        ),

        // Step 7: Display any error reported while saving.
        Notify(
            "Failed to save the filter: " &
            Coalesce(
                FirstError.Message,
                "An unknown error occurred."
            ),
            NotificationType.Error
        )
    )
)

